var L_paddle_models_js=globalThis.I18n||{t:(s,v)=>v?s.replace(/\{(\w+)\}/g,(m,k)=>v[k]??m):s,error:s=>s,locale:undefined};
/* Optional local PaddleOCR assets. Preparation is explicit; inference never fetches weights. */
(function(root){
 const CACHE='akai-paddle-024',base='models/paddle/';
 const models=['PP-OCRv5_mobile_det','PP-OCRv5_mobile_rec','korean_PP-OCRv5_mobile_rec'];
 const paths=[...models.map(n=>base+n+'.tar'),'vendor/paddle/sdk.mjs','vendor/paddle/opencv.mjs','vendor/paddle/clipper.mjs','vendor/paddle/yaml.mjs','vendor/paddle/ort.mjs','vendor/paddle/ort-wasm-simd-threaded.mjs','vendor/paddle/ort-wasm-simd-threaded.wasm'];
 const url=p=>new URL(p,location.href).href;
 async function status(){if(!('caches'in root))return {id:'paddle',ready:false,count:0,bytes:0,state:L_paddle_models_js.t("저장소 미지원")};const cache=await caches.open(CACHE);let count=0,bytes=0;for(const p of paths){const r=await cache.match(url(p));if(r){count++;bytes+=Number(r.headers.get('content-length'))||0}}return {id:'paddle',ready:count===paths.length,count,bytes,state:count===paths.length?L_paddle_models_js.t("사용 가능"):count?L_paddle_models_js.t("일부 준비됨"):L_paddle_models_js.t("미준비")}}
 async function prepare(signal,progress=()=>{}){const cache=await caches.open(CACHE);for(let i=0;i<paths.length;i++){if(signal?.aborted)throw new DOMException(L_paddle_models_js.t("취소됨"),'AbortError');const p=paths[i],u=url(p);if(await cache.match(u))continue;progress(L_paddle_models_js.t("OCR 다운로드 · {p0}/{p1} · {p2} · 서버 응답 대기",{p0:(i+1),p1:(paths.length),p2:(p.split('/').pop())}));const response=await fetch(u,{signal});if(!response.ok)throw Error(L_paddle_models_js.t("파일 다운로드 실패: ")+p);let bytes;if(response.body?.getReader){const reader=response.body.getReader(),parts=[];let received=0,last=0;const total=Number(response.headers.get('content-length'))||0;while(true){const {done,value}=await reader.read();if(done)break;if(signal?.aborted){await reader.cancel();throw new DOMException(L_paddle_models_js.t("취소됨"),'AbortError')}parts.push(value);received+=value.length;if(Date.now()-last>250){last=Date.now();progress(L_paddle_models_js.t("OCR 다운로드 · {p0}/{p1} · {p2}MB{p3}",{p0:(i+1),p1:(paths.length),p2:((received/1048576).toFixed(1)),p3:(total?' / '+(total/1048576).toFixed(1)+'MB':'')}))}}const buffer=new Uint8Array(received);let offset=0;for(const part of parts){buffer.set(part,offset);offset+=part.length}bytes=buffer.buffer}else bytes=await response.arrayBuffer();progress(L_paddle_models_js.t("OCR 저장 중 · {p0}/{p1}",{p0:(i+1),p1:(paths.length)}));if(signal?.aborted)throw new DOMException(L_paddle_models_js.t("취소됨"),'AbortError');if(bytes.byteLength<100)throw Error(L_paddle_models_js.t("잘못된 실행 파일: ")+p);if(p.endsWith('.tar')&&new TextDecoder().decode(bytes.slice(257,262))!=='ustar')throw Error(L_paddle_models_js.t("잘못된 모델 파일: ")+p);await cache.put(u,new Response(bytes,{headers:{'content-type':response.headers.get('content-type')||'application/octet-stream','content-length':String(bytes.byteLength)}}))}return status()}
 async function remove(){await caches.delete(CACHE);for(const name of await caches.keys()){if(!name.startsWith('akai-beta-'))continue;const cache=await caches.open(name);for(const p of paths)await cache.delete(url(p))}}
 root.PaddleModels={CACHE,models,paths,status,prepare,remove};
})(globalThis);
